def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no opponents, just bid enough to get water while conserving budget
    if not alive:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                bval = float(b)
                prev_bids.append(bval)
                prev_by_id[oid] = bval
            except Exception:
                pass

    # Estimate contest pressure
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Cindy appears to be the main aggressor when her bid was high yesterday
    cindy_bid = 0.0
    if 'Cindy' in opponents_status and opponents_status['Cindy'].get('alive', False):
        prev = opponents_status['Cindy'].get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                cindy_bid = float(b)
            except Exception:
                cindy_bid = 0.0

    # Supply pressure: higher supply reduces urgency to overpay
    # Normalize to [0,1]
    if MAX_SUPPLY - MIN_SUPPLY <= 0:
        supply_factor = 0.5
    else:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_factor = max(0.0, min(1.0, supply_factor))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Dynamic target bid
    # If someone paid near/above salary, we must match to avoid being starved.
    # Otherwise, bid moderately above the highest recent bid.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = highest_prev_bid / DAILY_SALARY

    # Base aggressiveness: more aggressive when supply is high (more water to allocate, but also more competition)
    # and when my hp is lower.
    hp_factor = 0.0
    if hp <= 2.0:
        hp_factor = 1.0
    elif hp <= 4.0:
        hp_factor = 0.7
    else:
        hp_factor = 0.4

    # Compute a desired bid ceiling
    # Keep a reserve so we can keep bidding later
    # (roughly 2 days of salary reserve)
    reserve = DAILY_SALARY * 2.0
    effective_budget = max(0.0, budget - reserve)

    # If Cindy was very aggressive yesterday, anticipate similar behavior.
    if cindy_bid >= DAILY_SALARY * 1.2:
        target = cindy_bid + 2.0
    elif pressure >= 1.0:
        target = highest_prev_bid + 1.0
    else:
        # Moderate: aim slightly above highest bid to win but not overspend
        target = max(DAILY_SALARY * (0.45 + 0.25 * (1.0 - supply_factor)) , highest_prev_bid + 0.5)

    # Adjust for my hp urgency and supply
    # Higher supply_factor => slightly less urgent
    target *= (0.85 + 0.3 * hp_factor)
    target *= (0.95 + 0.15 * (1.0 - supply_factor))

    # Final bid: bounded by budget and a reasonable fraction of salary
    # Since bids are monetary, cap at 1.6*salary to avoid runaway.
    cap = min(budget, DAILY_SALARY * 1.6)
    bid = min(cap, target)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # 1. If no opponents, bid minimal to save budget
    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.05)

    # 2. Survival Mode: If HP is very low or no water for 1 day, bid very high
    #    Also consider late game desperation
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        # If it's a very late day and I'm low on HP, go almost all in
        if current_day >= EPISODE_DAYS - 2 and my_status['hp'] <= 3:
            return min(my_status['budget'], DAILY_SALARY * 0.99)
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # 3. Analyze opponents' previous bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # 4. Determine competitive bid (water is always scarce for multiple players given supply range)
    base_competitive_bid = DAILY_SALARY * 0.6 
    my_calculated_bid = base_competitive_bid # Default competitive bid

    if highest_prev_bid > 0:
        # If highest_prev_bid is very high, I need to beat it significantly to guarantee win
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            my_calculated_bid = highest_prev_bid + 10.0
        # If highest_prev_bid is moderate, beat it by a smaller margin
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            my_calculated_bid = highest_prev_bid + 5.0
        # If highest_prev_bid is low, ensure I win it
        else:
            my_calculated_bid = max(base_competitive_bid, highest_prev_bid + 2.0)

    # Further adjust if my HP is getting low (but not critical survival mode yet)
    if my_status['hp'] <= 5:
        my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.75) # Be more aggressive
    elif my_status['hp'] > 5: # Healthy, can be slightly less aggressive if not needed
        my_calculated_bid = max(my_calculated_bid, DAILY_SALARY * 0.5)

    # 5. Budget Constraint & Minimum Bid
    final_bid = min(my_status['budget'], my_calculated_bid)

    # Ensure bid is at least 1.0 if I have budget and need water
    if my_status['hp'] <= 8 and my_status['budget'] > 0 and final_bid < 1.0:
        final_bid = 1.0

    return max(1.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    # Determine alive opponents with previous trace
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    yesterday_max_bid = 0.0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev['bid']
            if bid > yesterday_max_bid:
                yesterday_max_bid = bid

    hp = int(my_status['hp'])
    budget = int(my_status['budget'])

    # Base bid according to health
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 5:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.5

    # If we saw a high bid yesterday, attempt to slightly outdo it
    if yesterday_max_bid > 0:
        target = yesterday_max_bid + 2.0
        if target > base_bid:
            base_bid = target

    # Ensure we don't exceed budget
    final_bid = min(budget, base_bid)
    # Also ensure non-negative
    if final_bid < 0:
        final_bid = 0.0
    return final_bid
